package com.cappleapple.astralrepository.platform.fluids.capability.templates;
import com.cappleapple.astralrepository.platform.fluids.*;import com.cappleapple.astralrepository.platform.fluids.capability.*;import net.minecraft.core.HolderLookup;import net.minecraft.nbt.*;
public class FluidTank implements IFluidHandler {
 private final int capacity;private FluidStack fluid=FluidStack.EMPTY;public FluidTank(int capacity){this.capacity=capacity;}protected void onContentsChanged(){}public int getTanks(){return 1;}public FluidStack getFluid(){return fluid;}public int getFluidAmount(){return fluid.getAmount();}public int getCapacity(){return capacity;}public FluidStack getFluidInTank(int tank){return fluid;}public int getTankCapacity(int tank){return capacity;}public boolean isFluidValid(int tank,FluidStack stack){return true;}public void setFluid(FluidStack stack){fluid=stack.copyWithAmount(Math.min(capacity,stack.getAmount()));onContentsChanged();}
 public int fill(FluidStack stack,FluidAction action){if(stack.isEmpty()||(!fluid.isEmpty()&&!FluidStack.isSameFluidSameComponents(fluid,stack)))return 0;int n=Math.min(capacity-fluid.getAmount(),stack.getAmount());if(n>0&&action.execute()){fluid=stack.copyWithAmount(fluid.getAmount()+n);onContentsChanged();}return n;}
 public FluidStack drain(FluidStack stack,FluidAction action){return FluidStack.isSameFluidSameComponents(fluid,stack)?drain(stack.getAmount(),action):FluidStack.EMPTY;}public FluidStack drain(int maxDrain,FluidAction action){int n=Math.min(fluid.getAmount(),Math.max(0,maxDrain));var result=fluid.copyWithAmount(n);if(n>0&&action.execute()){fluid=fluid.copyWithAmount(fluid.getAmount()-n);onContentsChanged();}return result;}
 public CompoundTag writeToNBT(HolderLookup.Provider registries,CompoundTag tag){tag.put("Fluid",fluid.save(registries));return tag;}public FluidTank readFromNBT(HolderLookup.Provider registries,CompoundTag tag){fluid=FluidStack.parseOptional(registries,tag.getCompoundOrEmpty("Fluid"));return this;}
}
